bounds.text:
.detail-dialog.opponent-dialog[open] {border-color:#3f606b;width:min(650px,calc(100vw - var(--safe-left) - var(--safe-right) - 24px));height:auto;top:calc(50% + (var(--safe-top) - var(--safe-bottom)) / 2);bottom:auto;transform:translateY(-50%)}
.opponent-dialog .dialog-content {overflow:auto}
.opponent-dialog .dialog-scroll {height:auto;overflow:visible}
.opponent-dialog .dialog-eyebrow {display:block;color:#3f606b}
.opponent-dialog .dialog-effect {font-size:17px;color:#26313a;white-space:pre-line}
.opponent-dialog .dialog-purchase-summary {color:#3f606b;font-size:15px}
.opponent-dialog .opponent-quote {font-size:21px;font-weight:700;color:#3f606b;margin:0 0 12px}
.opponent-dialog .opponent-options {display:grid;gap:10px;margin:12px 0}
.opponent-dialog .opponent-option {border:1px solid #c7b89d;padding:10px;border-radius:6px;background:#fff9ee}
.opponent-dialog .opponent-option p {font-size:14px;line-height:1.6;white-space:pre-line;margin:8px 0 0}
.opponent-dialog .opponent-option button {min-height:44px;width:100%;font-weight:700}
.opponent-beat {box-sizing:border-box;position:fixed;z-index:12;pointer-events:none;background:#fff9ee;color:#26313a;border:1px solid #3f606b;border-left:5px solid #3f606b;padding:10px 14px;font-family:"Microsoft YaHei", "PingFang SC", "Noto Sans SC", sans-serif;display:flex;flex-direction:column;justify-content:center;gap:7px;overflow:hidden}
.opponent-beat[data-kind="repeat"] {border-color:#b8473a}
.opponent-beat small {font-size:14px;color:#59646a}
.opponent-beat strong {font-size:21px;line-height:1.25}
.opponent-beat p {font-size:15px;line-height:1.35;margin:0}
.opponent-beat[data-compact="true"] {padding:2px 10px;gap:2px;justify-content:flex-end}
.opponent-beat[data-compact="true"] small {line-height:1.25}
.opponent-beat[data-compact="true"] strong {font-size:18px}
.opponent-beat > small,.opponent-beat > strong,.opponent-beat > p {flex-shrink:0}
.opponent-dialog .opponent-identity {display:flex;align-items:center;gap:10px;margin:0 0 10px;color:#3f606b}
.opponent-dialog .opponent-seal {display:grid;place-items:center;border:2px solid currentColor;width:44px;height:44px;font:700 19px Georgia,serif;letter-spacing:2px}
.opponent-dialog .opponent-identity span {font-size:13px;letter-spacing:2px}
.opponent-dialog .opponent-quote {font-family:Georgia,'Noto Serif SC',SimSun,serif;font-size:clamp(20px,3vw,28px);line-height:1.3}
.opponent-dialog .dialog-effect {border-left:3px solid #b8473a;padding-left:12px;font-weight:700}
.opponent-dialog .dialog-purchase-summary {font-size:16px;font-weight:700}
.opponent-beat {background:#fff9ee;border-left-width:5px;gap:5px}
.opponent-beat strong {font-family:Georgia,'Noto Serif SC',SimSun,serif;font-size:clamp(19px,3vw,30px)}
.opponent-beat p {font-weight:700;color:#3f606b}
.opponent-beat[data-kind='repeat'] p {color:#b8473a}
.opponent-beat[data-kind='won'] {border-color:#7b7365}
.opponent-beat .opponent-receipt {align-self:flex-start;border:1px solid currentColor;padding:2px 6px;font-size:12px;letter-spacing:1px;color:#3f606b}
.opponent-beat[data-compact='true'] .opponent-receipt {display:none}
@media(min-width:700px) {.opponent-dialog .opponent-options {grid-template-columns:1fr 1fr}}
@media(max-height:620px) {.opponent-dialog .opponent-quote {font-size:18px;margin-bottom:6px}.opponent-dialog .opponent-options {gap:6px;margin:6px 0}.opponent-dialog .opponent-option {padding:7px}}
回音墙 · 同招回响“同一招，我听过了。”牌型基础 35 → 17.5同招 · 认出了

